# frozen_string_literal: true

require "connectrpc"
require "connectrpc/bindings/google_protobuf"
# Generated by `mise run generation:build` from examples/proto/demo/v1/demo.proto.
$LOAD_PATH.unshift(File.expand_path("../gen", __dir__))
require "demo/v1/demo_connect"

module DemoExample
  # One handler per RPC, shared by every example server so the server files
  # differ only in how they host ConnectRPC.
  class Handlers
    def initialize(served_by)
      @served_by = served_by
    end

    # The generated helper checks that every RPC has a handler.
    def to_h
      Demo::V1::DemoService.handlers(greet: method(:greet), countdown: method(:countdown),
                                     collect: method(:collect), chat: method(:chat))
    end

    # Unary: one request, one response. An empty name shows a typed error.
    def greet(request, context)
      raise ConnectRPC::Error.new(:invalid_argument, "name is required") if request.name.empty?

      context.response_metadata.add("demo-served-by", @served_by)
      context.response_trailers.add("demo-greeted", request.name)
      Demo::V1::GreetResponse.new(greeting: "Hello, #{request.name}!")
    end

    # Server streaming: send any number of responses, then return.
    def countdown(request, writer, context)
      raise ConnectRPC::Error.new(:invalid_argument, "from must be 1..10") unless (1..10).cover?(request.from)

      context.response_metadata.add("demo-served-by", @served_by)
      request.from.downto(1) { |number| writer.send_message(Demo::V1::CountdownResponse.new(number: number)) }
      context.response_trailers.add("demo-countdown", "done")
    end

    # Client streaming: read every request, then return exactly one response.
    def collect(reader, context)
      names = []
      reader.each { |message| names << message.name } # rubocop:disable Style/MapIntoArray -- readers have no map.
      context.response_metadata.add("demo-served-by", @served_by)
      Demo::V1::CollectResponse.new(summary: "Collected #{names.size} names: #{names.join(', ')}")
    end

    # Bidirectional streaming: reply to each message as soon as it arrives.
    def chat(duplex, context)
      context.response_metadata.add("demo-served-by", @served_by)
      duplex.each { |message| duplex.send_message(Demo::V1::ChatResponse.new(text: "Hello, #{message.text}!")) }
    end
  end

  # Prints one line per RPC describing what actually arrived, read from the
  # request headers the server saw:
  #
  #   served Greet request-id=1f2e3d4c protocol=connect http=POST codec=json encoding=gzip code=OK
  #
  # A Connect GET has no body, so no content headers; its codec and compression
  # travel in the query string instead. For GET the line reports the codec and
  # encoding the server answered with, which it chose from that query and the
  # client's Accept-Encoding.
  class CallLog
    # Instrumentation calls start once per RPC; the returned observer receives the outcome.
    def start(call) = Observer.new(call)

    Observer = Struct.new(:call) do
      def processing_finished(outcome)
        request = call.carrier
        http = http_method(outcome)
        headers = http == "GET" ? outcome.response_metadata : request
        $stdout.write("served #{call.method&.name} request-id=#{first(request, 'demo-request-id')} " \
                      "protocol=#{call.protocol} http=#{http} codec=#{codec(headers)} " \
                      "encoding=#{encoding(headers)} code=#{outcome.code || '-'}\n") # One write keeps lines whole.
      end

      private

      # Inferred, not observed: only a Connect GET reaches the handler without a
      # content-type, and a request rejected before dispatch has no code.
      def http_method(outcome)
        return "-" unless outcome.code

        call.carrier.key?("content-type") ? "POST" : "GET"
      end

      def first(headers, name) = headers.fetch(name, ["-"]).first

      def codec(headers)
        case first(headers, "content-type")
        when /json\z/ then "json"
        when /proto\z/, "application/grpc" then "proto"
        else "unknown"
        end
      end

      # Connect unary, Connect streaming and gRPC each name compression differently.
      def encoding(headers)
        values = headers.values_at("content-encoding", "connect-content-encoding", "grpc-encoding").compact
        values.first&.first || "identity"
      end
    end
  end

  def self.instrumentation = ConnectRPC::Instrumentation.new(subscribers: [CallLog.new])

  # Every server accepts gzip and both codecs. Native HTTP/2 hosts pass
  # `protocol: :auto` to serve Connect and gRPC on the same port.
  def self.connect_server(served_by:, protocol: :connect)
    ConnectRPC::Server.new(services: [Demo::V1::DemoService::SERVICE], binding: ConnectRPC::Bindings::GoogleProtobuf.new,
                           handlers: Handlers.new(served_by).to_h, protocol: protocol, encoding: :gzip,
                           instrumentation: instrumentation)
  end
end
